  "campaign.dmCatalog.aoe_damage.field.damage.placeholder": "8d6",
  "campaign.dmCatalog.aoe_damage.field.damage.help": "Leave blank for a spell that deals no damage (such as Entangle). A known spell rolls its own damage.",
  "campaign.dmCatalog.aoe_damage.field.saveAbility.label": "Saving throw",
  "campaign.dmCatalog.aoe_damage.field.saveAbility.help": "Required if no spell is named, such as for a trap. Character and enemy spells specify their own save.",
  "campaign.dmCatalog.aoe_damage.field.dc.label": "Saving throw DC",
  "campaign.dmCatalog.aoe_damage.field.dc.help": "Required together with the saving throw when no spell is named.",
