  "campaign.dmCatalog.aoe_damage.field.halfOnSave.label": "Half damage on a successful save",
  "campaign.dmCatalog.aoe_damage.field.condition.label": "Condition on a failed save",
  "campaign.dmCatalog.aoe_damage.field.condition.help": "When no spell or enemy is named, use this for a class feature or a trap.",
