  "campaign.dmCatalog.aoe_damage.field.overchannel.help": "An evoker's maximum damage. The server rolls the cost of using Overchannel a second time.",
  "campaign.dmCatalog.aoe_damage.field.sparedCharacterIds.label": "Allies protected by Sculpt Spells",
