  "campaign.dmCatalog.grant_item.field.additional.help": "When item offers are enabled, the same item offered again within ten minutes of an accepted offer is rejected unless it genuinely comes from a different source.",
  "campaign.dmCatalog.grant_item.field.srdName.help": "If the item is named in the campaign's language, enter the SRD or content-pack item it corresponds to, using its English name. This gives it the correct properties. For magic weapons or armor, enter both the magic name and its base item as written in the SRD, such as Flame Tongue Scimitar or Vicious Rapier.",
  "campaign.dmCatalog.grant_item.field.tags.help": "Enter comma-separated tags from this list: consumable, kept, durable, potion, healing_potion, scroll, food, water, everburning_light, bullseye_lantern, lantern, torch, candle, lamp_oil, lamp, cold_weather_gear, heavy_clothing, component_pouch, arcane_focus, holy_symbol, druidic_focus, instrument, tools, wand, staff, rod, arrows, bolts, bullets, needles, silvered, adamantine, gem, art_object, trade_good, carried. For an item not listed in the SRD or a content pack, enter all its properties; for a listed item, enter only what it adds (for example, silvered for a silvered longsword).",
  "campaign.dmCatalog.reveal_item.label": "Identify a mystery item",
