  "campaign.dmCatalog.reveal_item.field.tags.help": "Enter comma-separated tags from this list: consumable, kept, durable, potion, healing_potion, scroll, food, water, everburning_light, bullseye_lantern, lantern, torch, candle, lamp_oil, lamp, cold_weather_gear, heavy_clothing, component_pouch, arcane_focus, holy_symbol, druidic_focus, instrument, tools, wand, staff, rod, arrows, bolts, bullets, needles, silvered, adamantine, gem, art_object, trade_good, carried. For an item not listed in the SRD or a content pack, enter all its properties; for a listed item, enter only what it adds (for example, silvered for a silvered longsword).",
  "campaign.dmCatalog.remove_item.label": "Remove an item",
  "campaign.dmCatalog.remove_item.summary": "Permanently removes an item if it was stolen or destroyed. To drop it on the ground, use Handle an item; consumables being used go through Use an item.",
