  "campaign.dmCatalog.handle_item.field.item.label": "Item",
  "campaign.dmCatalog.handle_item.field.qty.label": "Quantity",
  "campaign.dmCatalog.handle_item.field.srdName.help": "Only for an enemy's dropped item. If it is named in the campaign's language, enter the SRD or content-pack item it corresponds to, using its English name. For magic weapons or armor, enter both the magic name and its base item as written in the SRD, such as Flame Tongue Scimitar or Vicious Rapier.",
  "campaign.dmCatalog.handle_item.field.tags.help": "Only for an enemy's dropped item. Enter comma-separated tags from this list: consumable, kept, durable, potion, healing_potion, scroll, food, water, everburning_light, bullseye_lantern, lantern, torch, candle, lamp_oil, lamp, cold_weather_gear, heavy_clothing, component_pouch, arcane_focus, holy_symbol, druidic_focus, instrument, tools, wand, staff, rod, arrows, bolts, bullets, needles, silvered, adamantine, gem, art_object, trade_good, carried. For an item not listed in the SRD or a content pack, enter all its properties; for a listed item, enter only what it adds.",
  "campaign.dmCatalog.handle_item.field.toCharacterId.label": "Give to",
  "campaign.dmCatalog.handle_item.field.helped.label": "With help",
  "campaign.dmCatalog.handle_item.field.helped.help": "Taking armor off with another person's help takes half the time.",
  "campaign.dmCatalog.use_item.label": "Use an item",
  "campaign.dmCatalog.use_item.summary": "Consumes an item and applies its effect, resolving potion rolls according to the rules.",
