  "campaign.dmCatalog.use_item.field.charges.help": "For a wand or staff: the item remains, but its charge count decreases. Charges return at dawn.",
  "campaign.dmCatalog.use_item.field.spell.label": "Spell cast from the item",
  "campaign.dmCatalog.use_item.field.spell.help": "Enter the spell the item casts (for example, a wand's Fireball or a hat's Disguise Self). The item sets its level, so this spell form does not spend a spell slot.",
