  "campaign.sound.blurb.dungeon": "Cold stone corridors, a far-off drip, the room breathing.",
  "campaign.sound.blurb.cave": "Dripping water in a wide dark space, air moving through rock.",
  "campaign.sound.blurb.crypt": "Tomb silence with something shifting in it.",
  "campaign.sound.blurb.sewer": "Running filth, echoing brick, rats where you cannot see them.",
  "campaign.sound.blurb.mine": "Timbers under strain, a pick working somewhere below.",
  "campaign.sound.blurb.ruins": "Wind through broken walls and whatever nests in them.",
  "campaign.sound.blurb.temple": "A high vaulted hush, distant voices at prayer.",
  "campaign.sound.blurb.forest": "Birdsong, leaves moving, a wood going about its day.",
  "campaign.sound.blurb.deep_forest": "Owls, insects, and branches that are probably the wind.",
  "campaign.sound.blurb.jungle": "Wet heat, insects in layers, birds that sound like screams.",
  "campaign.sound.blurb.swamp": "Frogs, flies, and water that will not hold your weight.",
  "campaign.sound.blurb.desert": "Dry wind over sand and nothing else at all.",
  "campaign.sound.blurb.mountain": "Thin high wind over bare rock.",
  "campaign.sound.blurb.tundra": "Driving snow and cold that has weight to it.",
  "campaign.sound.blurb.plains": "Grass moving, larks overhead, a long way to anywhere.",
  "campaign.sound.blurb.river": "Water moving steadily past a bank.",
  "campaign.sound.blurb.waterfall": "Falling water loud enough to talk under.",
  "campaign.sound.blurb.coast": "Surf on shingle and gulls arguing about it.",
  "campaign.sound.blurb.ship": "Timbers working, rigging, and the sea under everything.",
  "campaign.sound.blurb.underwater": "Everything muffled, everything slow, bubbles going up.",
  "campaign.sound.blurb.town": "Carts, chickens, hammering, a dog making its case.",
  "campaign.sound.blurb.city": "A street with too many people on it and traffic of some kind.",
  "campaign.sound.blurb.market": "Hawkers, haggling, livestock, someone dropping something.",
  "campaign.sound.blurb.crowd": "A press of people close enough to touch you.",
  "campaign.sound.blurb.tavern": "Fire, mugs, low talk, and someone murdering a lute.",
  "campaign.sound.blurb.camp": "A fire going, night around it, watch being kept.",
  "campaign.sound.blurb.keep": "A big fire in a bigger room, banners moving in the draught.",
  "campaign.sound.blurb.library": "Pages, a distant cough, and the sound of being told to be quiet.",
  "campaign.sound.blurb.forge": "Bellows, hammer on anvil, metal complaining.",
  "campaign.sound.blurb.graveyard": "Wind, crows, and wet grass between the stones.",
  "campaign.sound.blurb.arcane": "A hum with no source, and air that feels used.",
  "campaign.sound.blurb.wind": "Wind with nothing to say about where you are.",
  "campaign.sound.blurb.rain": "Steady rain on whatever is over your head.",
  "campaign.sound.blurb.storm": "Wind, rain and thunder taking turns.",
  "campaign.sound.blurb.night": "Crickets, an owl, the world with the lights off.",
  "campaign.sound.blurb.calm": "Nothing is wrong yet. Rest, shopping, talking it over.",
  "campaign.sound.blurb.wonder": "They have just seen something worth the trip.",
  "campaign.sound.blurb.mystery": "Something does not add up and they have noticed.",
  "campaign.sound.blurb.tension": "It has not gone wrong yet, and it is going to.",
  "campaign.sound.blurb.dread": "The scene where they should have run.",
  "campaign.sound.blurb.battle": "A fight worth rolling initiative for.",
  "campaign.sound.blurb.boss": "The fight the campaign has been walking towards.",
  "campaign.sound.blurb.chase": "Someone is running and someone else is closing.",
  "campaign.sound.blurb.triumph": "They won and everyone should hear about it.",
  "campaign.sound.blurb.sorrow": "A death, a betrayal, or the cost coming due.",
  "campaign.sound.blurb.travel": "Miles passing under them without incident.",
  "campaign.sound.blurb.festive": "A feast, a fair, a wedding, a coronation.",
  "campaign.sound.blurb.thunder": "Close enough to feel.",
  "campaign.sound.blurb.door_slam": "The way out just stopped being one.",
  "campaign.sound.blurb.door_creak": "Slowly, and not by anyone's hand.",
  "campaign.sound.blurb.roar": "Something large announcing itself.",
  "campaign.sound.blurb.wolf_howl": "A howl, then answers from three directions.",
  "campaign.sound.blurb.horn": "Someone has called for help, or for blood.",
  "campaign.sound.blurb.bell": "A single toll, and everyone stops talking.",
  "campaign.sound.blurb.gong": "For arrivals nobody wanted.",
  "campaign.sound.blurb.scream": "From somewhere they have not been yet.",
  "campaign.sound.blurb.sword_clash": "The moment a talk became a fight.",
  "campaign.sound.blurb.magic_cast": "Whatever that was, it worked.",
  "campaign.sound.blurb.coin": "Payment, bribe, or a purse hitting a table.",
  "campaign.sound.blurb.crow": "They lift off all at once, which is never nothing.",
  "campaign.sound.blurb.heartbeat": "For the pause before a death save.",
  "campaign.sound.blurb.chain": "Something is being let off a chain, or put back on one.",
  "campaign.sound.blurb.splash": "Someone or something went in.",
  "campaign.sound.blurb.hit_melee": "A weapon connects.",
  "campaign.sound.blurb.hit_ranged": "A shot finds its mark.",
  "campaign.sound.blurb.hit_crit": "A blow that changes the fight.",
  "campaign.sound.blurb.swing_miss": "Air, and nothing else.",
  "campaign.sound.blurb.spell_fire": "A rush of flame.",
  "campaign.sound.blurb.spell_cold": "Frost crackling over everything.",
  "campaign.sound.blurb.spell_thunder": "A crack that rattles teeth.",
  "campaign.sound.blurb.spell_radiant": "A chord of light.",
  "campaign.sound.blurb.spell_dark": "Something cold drawn out of someone.",
  "campaign.sound.blurb.heal": "Warmth returning.",
  "campaign.sound.blurb.death": "Low and final.",
  "campaign.sound.blurb.door_locked": "A handle that will not turn.",
  "campaign.sound.blurb.door_secret": "Stone grinding where there was no door.",
  "campaign.sound.blurb.thud": "Something heavy meets the ground.",
  "campaign.sound.blurb.turn": "A short chime for the person whose turn it is.",
