  "campaign.session.eventLog.confirm.revertDescription": "This puts the character sheets, the clock and the fight back as they were before the turn: hit points, conditions, creatures that came or fell, tokens, areas on the board, effects and whose turn it is. A fight the turn began goes; the fight's prepared events are armed again, a test's forced dice given back and a card resolved as played waits again. World events and companions who left stay; rewinding the chapter takes those back.",
