  "campaign.session.condition.rule.blinded": "Can't see, and fails any ability check that needs sight. Attacks against it have advantage; its own attacks have disadvantage.",
  "campaign.session.condition.rule.charmed": "Can't attack the charmer or target them with harmful abilities or magical effects. The charmer has advantage on ability checks to interact socially with it.",
  "campaign.session.condition.rule.deafened": "Can't hear, and fails any ability check that needs hearing.",
  "campaign.session.condition.rule.frightened": "Disadvantage on ability checks and attack rolls while the source of its fear is within line of sight. Can't willingly move closer to that source.",
  "campaign.session.condition.rule.grappled": "Speed 0, and no bonus can raise it. Ends if the grappler is incapacitated, or if an effect takes it out of the grappler's reach.",
  "campaign.session.condition.rule.incapacitated": "Can't take actions or reactions.",
  "campaign.session.condition.rule.invisible": "Impossible to see without magic or a special sense; for hiding it is heavily obscured, though its noise or tracks can still give away where it is. Attacks against it have disadvantage; its own attacks have advantage.",
  "campaign.session.condition.rule.paralyzed": "Incapacitated, can't move or speak, and automatically fails Strength and Dexterity saves. Attacks against it have advantage, and any hit from within 5 feet is a critical hit.",
  "campaign.session.condition.rule.petrified": "Turned to stone with what it wears and carries, ten times as heavy and no longer aging: incapacitated, can't move or speak, unaware of its surroundings, and automatically fails Strength and Dexterity saves. Attacks against it have advantage; it resists all damage and is immune to poison and disease (one already in it is suspended).",
  "campaign.session.condition.rule.poisoned": "Disadvantage on attack rolls and ability checks.",
  "campaign.session.condition.rule.prone": "Can only crawl, or spend half its speed to stand. Disadvantage on its attack rolls. Attacks against it have advantage from within 5 feet, disadvantage from farther away.",
  "campaign.session.condition.rule.restrained": "Speed 0, and no bonus can raise it. Attacks against it have advantage, its own attacks have disadvantage, and it has disadvantage on Dexterity saves.",
  "campaign.session.condition.rule.stunned": "Incapacitated, can't move, and can speak only falteringly. Automatically fails Strength and Dexterity saves, and attacks against it have advantage.",
  "campaign.session.condition.rule.unconscious": "Incapacitated, can't move or speak, and unaware of its surroundings; drops what it holds and falls prone. Automatically fails Strength and Dexterity saves; attacks against it have advantage, and any hit from within 5 feet is a critical hit.",
  "campaign.session.condition.rule.concentrating": "Holding a spell. Each time it takes damage it makes a Constitution save, DC 10 or half the damage if higher, or loses it; it also ends on casting another concentration spell, or on being incapacitated or killed.",
  "campaign.session.condition.rule.dodging": "Until the start of its next turn, attacks against it have disadvantage if it can see the attacker, and it has advantage on Dexterity saves. Lost if it is incapacitated or its speed drops to 0.",
  "campaign.session.condition.rule.raging": "Out of heavy armor: advantage on Strength checks and saves, extra damage on melee weapon attacks using Strength, and resistance to bludgeoning, piercing and slashing damage. Can't cast or concentrate on spells. Ends early if it is knocked unconscious, or if its turn ends without it attacking a hostile creature or taking damage since its last turn.",
  "campaign.session.condition.rule.hidden": "Unseen and unheard. Attacks against it have disadvantage, its own attacks have advantage, and an attack, hit or miss, gives away where it is.",
  "campaign.session.condition.rule.exhaustion": "Each level adds to those below it: 1, disadvantage on ability checks; 2, speed halved; 3, disadvantage on attack rolls and saves; 4, hit point maximum halved; 5, speed 0; 6, death. A long rest with food and drink lowers it by one level.",
  "campaign.session.condition.rule.exhaustion1": "Level 1: disadvantage on ability checks. A long rest with food and drink lowers it by one level.",
  "campaign.session.condition.rule.exhaustion2": "Level 2: disadvantage on ability checks; speed halved. A long rest with food and drink lowers it by one level.",
  "campaign.session.condition.rule.exhaustion3": "Level 3: disadvantage on ability checks; speed halved; disadvantage on attack rolls and saves. A long rest with food and drink lowers it by one level.",
  "campaign.session.condition.rule.exhaustion4": "Level 4: disadvantage on ability checks; speed halved; disadvantage on attack rolls and saves; hit point maximum halved. A long rest with food and drink lowers it by one level.",
  "campaign.session.condition.rule.exhaustion5": "Level 5: disadvantage on ability checks; speed 0; disadvantage on attack rolls and saves; hit point maximum halved. A long rest with food and drink lowers it by one level.",
  "campaign.session.condition.rule.exhaustion6": "Level 6: death.",
